chapter.section:
Hazards


  Hazards are traps, environmental dangers, and mystical effects that are
  usually antagonistic to the PCs. They provide the mechanism for resolving
  conflict between PCs and their environment.






{% from "docs/macro_ability.xml" import build_ability with context %}

{% for ag in ability_groups if ag.is_hazards_family() %}

  {{ ag.get_name() }}

  {{ ag.get_description() }}

  {% for ability in ag.get_abilities()%}
  {{ build_ability(ability) }}
  {% endfor %}

{% endfor %}
